package com.renthouse.review;import com.renthouse.auth.*;import com.renthouse.common.exception.BusinessException;import com.renthouse.common.id.SnowflakeIdGenerator;import java.time.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ReviewService{private final JdbcTemplate j;private final SnowflakeIdGenerator ids;public ReviewService(JdbcTemplate j,SnowflakeIdGenerator ids){this.j=j;this.ids=ids;}@Transactional public void create(long contractId,int rating,String content){CurrentUser.requireRole(UserRole.TENANT);long t=CurrentUser.require().id();Long l=j.query("SELECT landlord_id FROM tenancy_contract WHERE id=? AND tenant_id=? AND status IN ('TERMINATED','EXPIRED','CHECKOUT_PENDING')",r->r.next()?r.getLong(1):null,contractId,t);if(l==null)throw new BusinessException("REVIEW_NOT_ALLOWED","当前合同不可评价",HttpStatus.CONFLICT);try{j.update("INSERT INTO review(id,contract_id,tenant_id,landlord_id,rating,content,created_at) VALUES(?,?,?,?,?,?,?)",ids.nextId(),contractId,t,l,rating,content,LocalDateTime.now());}catch(Exception e){throw new BusinessException("REVIEW_EXISTS","该合同已评价",HttpStatus.CONFLICT);}}@Transactional public void reply(long reviewId,String content){CurrentUser.requireRole(UserRole.LANDLORD);int n=j.update("UPDATE review SET reply_content=?,replied_at=? WHERE id=? AND landlord_id=? AND replied_at IS NULL",content,LocalDateTime.now(),reviewId,CurrentUser.require().id());if(n==0)throw new BusinessException("REVIEW_REPLY_INVALID","评价不存在、无权限或已回复",HttpStatus.CONFLICT);}}
